param(
    [Parameter(Mandatory=$true)][string]$GatePath,
    [switch]$AllowPendingFinalReview,
    [ValidatePattern('^[0-9a-fA-F]{64}$')][string]$ExpectedGateSha256
)

$ErrorActionPreference='Stop';$prefix='paper-text-v1-multiseed-cap128-r14-20260831';$children=@("$prefix-split42-model42","$prefix-split43-model43");$bulkRoot='E:\blp\sleep_stage_reproduction';$logRoot=Join-Path $bulkRoot 'runtime\training-logs';$resolved=(Resolve-Path -LiteralPath $GatePath).Path;$hash=(Get-FileHash -LiteralPath $resolved -Algorithm SHA256).Hash.ToLowerInvariant();if(-not[string]::IsNullOrWhiteSpace($ExpectedGateSha256)-and$hash-ne$ExpectedGateSha256.ToLowerInvariant()){throw 'r14 gate SHA mismatch'}
$gate=Get-Content -LiteralPath $resolved -Raw|ConvertFrom-Json -ErrorAction Stop
if($gate.schema_version-ne2-or$gate.artifact_type-ne'canonical_r14_multiseed_launch_gate'-or$gate.publication_is_not_launch-ne$true-or$gate.run_id_prefix-ne$prefix-or(@($gate.seeds)-join'|')-ne'42|43'-or(@($gate.expected_children)-join'|')-ne($children-join'|')){throw 'r14 gate identity failed'}
if($AllowPendingFinalReview){if($gate.status-ne'pending_final_review'-or$gate.fresh_launch_authorized-ne$false){throw 'r14 pending gate boundary failed'}}else{if($gate.status-ne'pass'-or$gate.fresh_launch_authorized-ne$true){throw 'r14 final gate status failed'}}
$p=$gate.protocol;if($p.protocol_id-ne'PAPER_TEXT_V1'-or$p.command-ne'multi-seed-pilot'-or[int]$p.cap-ne128-or[int]$p.stage3_gradient_accumulation_steps-ne128-or$p.stage3_stability_adaptation_id-ne'PAPER_TEXT_STAGE3_GLOBAL_NORM_CLIP_V1'-or[double]$p.stage3_gradient_clip_norm-ne1.0-or$p.stage3_gradient_clip_application_point-ne'after_effective_batch_average_before_optimizer_step'-or$p.resume_forbidden-ne$true){throw 'r14 gate protocol failed'}
$d=$gate.durable_supervisor;if($d.design_id-ne'R14_WINDOWS_TASK_SCHEDULER_SCALAR_ACTION_E_STAGED_V1'-or$d.production_supervisor_path-ne'E:\blp\sleep_stage_reproduction\runtime\driver-recovery\r14-production-supervisor-v3.ps1'-or$d.production_supervisor_sha256-ne$d.local_template_sha256-or$d.scalar_action_arguments_required-ne$true-or[int]$d.maximum_action_arguments_length-ne1024-or$d.object_serialization_forbidden-ne$true-or$d.task_definition_validated_before_dispatch_marker-ne$true-or$d.automatic_restart_forbidden-ne$true){throw 'r14 durable supervisor gate failed'}
$x=$gate.exactly_once;$dispatch=Join-Path $logRoot "$prefix.dispatch.lock";$attempt=Join-Path $logRoot "$prefix.launch.lock";if($x.dispatch_marker-ne$dispatch-or$x.attempt_marker-ne$attempt-or$x.file_mode-ne'CreateNew'-or$x.file_share-ne'None'-or$x.no_retry_resume_reuse-ne$true-or$x.attempt_count-ne0-or$x.dispatch_marker_absent-ne$true-or$x.attempt_marker_absent-ne$true){throw 'r14 exactly-once gate failed'}
$launch=$gate.launch_test_evidence;if($launch.status-ne'pass'-or$launch.schema_version-ne2-or$launch.pilot_launched-ne$false-or$launch.sha256-ne'1a4fd2001627fac5e34506acc0f8f66e7142d97648b0365e8b0bef0f32058edd'){throw 'r14 launch evidence gate failed'}
if((Get-FileHash -LiteralPath ([string]$launch.local_path) -Algorithm SHA256).Hash.ToLowerInvariant()-ne$launch.sha256-or(Get-FileHash -LiteralPath ([string]$launch.canonical_path) -Algorithm SHA256).Hash.ToLowerInvariant()-ne$launch.sha256){throw 'r14 launch evidence files changed'}
$a=$gate.authorization;if($a.schema_version-ne2-or$a.artifact_type-ne'delegated_user_launch_authorization'-or$a.exact_user_excerpt_count-ne2-or$a.combined_excerpt_sha256-ne'1acefb63aa855c34e9fa1163d5818bac6f5ee80cbdbe406cf9058a4eba2c639e'-or$a.user_directly_requested_exact_r14_identity-ne$false-or$a.agent_interpretation_label-ne'agent_interpretation_not_user_quote'-or$a.present-ne$false-or$a.must_bind_exact_gate_sha256-ne$true-or$a.must_bind_all_source_hashes-ne$true){throw 'r14 delegated authorization gate failed'}
$bindings=@{};foreach($b in @($gate.source_bindings)){$name=[string]$b.name;if([string]::IsNullOrWhiteSpace($name)-or$bindings.ContainsKey($name)-or[string]$b.sha256-notmatch'^[0-9a-f]{64}$'){throw 'r14 gate source binding invalid'};$path=(Resolve-Path -LiteralPath ([string]$b.path)).Path;if((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()-ne[string]$b.sha256){throw "r14 gate source changed: $name"};$bindings[$name]=$b}
foreach($name in @('dispatcher_ps1','supervisor_ps1','supervisor_template_ps1','runner_sh','r14_exactly_once_helpers_ps1','launch_test_evidence_json','review_evidence_json','r14_canonical_gate_builder_ps1','r14_canonical_gate_smoke_ps1','r14_review_identity_refusal_smoke_ps1','r14_gate_builder_parameter_smoke_ps1','r14_confirmation_builder_ps1','r14_confirmation_smoke_ps1','cache_manifest_json','cache_validator_log')){if(!$bindings.ContainsKey($name)){throw "r14 gate binding absent: $name"}}
if($bindings.supervisor_ps1.sha256-ne$bindings.supervisor_template_ps1.sha256-or$bindings.launch_test_evidence_json.sha256-ne$launch.sha256-or$bindings.review_evidence_json.sha256-ne$gate.review_evidence.sha256){throw 'r14 gate evidence/source disagreement'}
$review=Get-Content -LiteralPath ([string]$gate.review_evidence.path) -Raw|ConvertFrom-Json -ErrorAction Stop;$reviews=@($gate.reviewer_bindings);if($review.schema_version-ne2-or$reviews.Count-ne3-or$reviews[0].status-ne'material_finding_closed'-or$reviews[0].finding_id-ne'R14-AUTH-PROVENANCE-001'-or$reviews[0].closure_status-ne'closed'){throw 'r14 initial finding closure missing'}
if($reviews[1].status-ne'material_finding_closed'-or$reviews[1].finding_id-ne'R14-BUILDER-DEFAULT-001'-or$reviews[1].closure_status-ne'closed'-or[string]::IsNullOrWhiteSpace([string]$reviews[1].agent_id)-or[string]$reviews[0].agent_id-eq[string]$reviews[1].agent_id){throw 'r14 builder finding closure missing'}
if($AllowPendingFinalReview){if($review.status-ne'pending_final_review'-or$reviews[2].status-ne'pending'-or-not[string]::IsNullOrWhiteSpace([string]$reviews[2].agent_id)){throw 'r14 pending reviewer state failed'}}else{if($review.status-ne'pass'-or$reviews[2].status-ne'no_material_finding'-or[string]::IsNullOrWhiteSpace([string]$reviews[2].agent_id)-or[string]$reviews[0].agent_id-eq[string]$reviews[2].agent_id-or[string]$reviews[1].agent_id-eq[string]$reviews[2].agent_id){throw 'r14 final reviewer state failed'}}
& "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -NoProfile -NonInteractive -ExecutionPolicy Bypass -File ([string]$bindings.r14_launch_test_evidence_smoke_ps1.path) -ExpectedSha256 $launch.sha256|Out-Null;if($LASTEXITCODE-ne0){throw 'r14 launch evidence validator rerun failed'}
$paths=@($dispatch,$attempt,(Join-Path $logRoot "$prefix.dispatch.lifecycle.jsonl"),(Join-Path $logRoot "$prefix.lifecycle.jsonl"))+@($children|%{Join-Path (Join-Path $bulkRoot 'runs') $_});$present=@($paths|?{Test-Path -LiteralPath $_});if($present.Count){throw 'r14 production namespace is not empty'}
[ordered]@{status='pass';gate_status=[string]$gate.status;fresh_launch_authorized=[bool]$gate.fresh_launch_authorized;pilot_launched=$false;gate_sha256=$hash;source_bindings=@($gate.source_bindings).Count;pending_final_review=[bool]$AllowPendingFinalReview;production_artifacts_present=0;validated_by_windows_powershell_5_1=$true}|ConvertTo-Json -Compress
